## Code Example

```javascript
const {BigQuery} = require('@google-cloud/bigquery');
const bigquery = new BigQuery();

exports.ingestSensor = async (message, context) => {
  const data = Buffer.from(message.data, 'base64').toString();
  let parsed;
  try { parsed = JSON.parse(data); } catch (e) { return; }
  if (!parsed.device || typeof parsed.ts === 'undefined' || typeof parsed.value !== 'number') {
    return;
  }
  const insertId = `${message.id}_${parsed.device}_${parsed.ts}`;
  await bigquery.dataset('iot').table('readings').insert([Object.assign({}, parsed, {insertId})]);
};
```

